preset.frame_eqs_eel:
vol_att=bass_att+treb_Att+mid_att;
bass_thresh = above(bass_att,bass_thresh)*2 + (1-above(bass_att,bass_thresh))*((bass_thresh-1.3)*0.96+1.3);
treb_thresh=above(treb_att,treb_thresh)*2+
(1-above(treb_att,treb_thresh))*((treb_thresh-1.3)*0.96+1.3);
mid_thresh=above(mid_att,mid_thresh)*2+
(1-above(mid_mid_att,mid_thresh))*((mid_thresh-1.3)*0.96+1.3);
vol_thresh=bass_thresh+treb_thresh+mid_thresh;
new_bass_thresh=bass_thresh+bass_effect-.2*sin(bass_thresh-new_bass_thresh+1);
new_treb_thresh=treb_thresh+treb_Effect-.2*sin(treb_thresh-new_treb_thresh+1);
new_mid_thresh=mid_thresh+mid_effect-.2*sin(mid_thresh-new_mid_thresh+1);
treb_effect=max(max(treb,treb_Att),treb_thresh);
bass_effect=max(max(Bass,bass_Att),bass_thresh);
mid_effect=max(max(mid,mid_att),mid_thresh);
vol_effect=bass_effect+treb_effect+mid_effect;
react=if(equal(new_vol,change),1,0);
new_bass=if(above(react,bass_effect),bass_thresh,new_bass_thresh);
new_treb=if(above(react,treb_effect),treb_thresh,new_treb_thresh);
new_mid=if(above(react,mid_effect),mid_thresh,new_mid_thresh);
new_vol=new_bass+new_treb+new_mid+.04;
change=bnot(1);
q1=new_bass;
q2=new_treb;
q3=new_mid;
q4=new_vol;
q5=if(above(q2,q3),above(q1,q3),-above(q1,q3));
q6=if(above(q1,q3),above(q2,q4),-above(q2,q3));
q7=if(above(q5,q6),q5,-q6);;
q8=if(above(q6,q7),q6,-q7);;

r=.2*sin(time*.13);
b=0+.3*sin(q1-time*.12);
g=0+.6*sin(time*.64-.2);
wave_b=g;
wave_r=r;
wave_g=b;
ob_r=r+.3;
ob_b=b+.3;
ob_g=g-.3;
